// Tell whether a character can see another tile without a wall blocking the view.
// line-of-sight: original MIT-licensed native educational port.
// Generated by tools/ports/generate.py; edit the specification to preserve parity.
// Input: [width,height,start_x,start_y,goal_x,goal_y,...grid]
// Output: [visible_flag]
// Integer tile centers; zero is transparent. Corner ties test both side cells to prevent diagonal
// wall leaks.
// Precondition: finite, correctly shaped data; integer indices/counts/IDs.
// See ../PORTS.md for examples, limits, and the shared test fixtures.

// Count how many numbers are in this list.
function port_length(a: number[]): number { return a.length; }
// Read one number at a zero-based position; stop if that position does not exist.
function port_get(a: number[], i: number): number { if (!Number.isInteger(i) || i < 0 || i >= a.length) throw new RangeError("index"); return a[i]; }
// Remove a negative sign so a distance or size is not negative.
function port_abs_num(a: number): number { return Math.abs(a); }

// 1. Walk a straight line from the starting tile center to the target tile center.
// 2. Check every tile touched by the line.
// 3. When the line crosses a corner, check both side tiles too.
// 4. Any wall blocks sight. This prevents seeing through two walls that meet diagonally.
export function compute(data: number[]): number[] {
    let w: number = 0;
    let h: number = 0;
    let x: number = 0;
    let y: number = 0;
    let gx: number = 0;
    let gy: number = 0;
    let nx: number = 0;
    let ny: number = 0;
    let sx: number = 0;
    let sy: number = 0;
    let ix: number = 0;
    let iy: number = 0;
    let decision: number = 0;
    w = port_get(data, 0);
    h = port_get(data, 1);
    x = port_get(data, 2);
    y = port_get(data, 3);
    gx = port_get(data, 4);
    gy = port_get(data, 5);
    if (((w < 1) || (h < 1) || (port_length(data) != (6 + (w * h))))) {
        return [-(1)];
    }
    if (((x < 0) || (y < 0) || (gx < 0) || (gy < 0) || (x >= w) || (gx >= w) || (y >= h) || (gy >= h))) {
        return [0];
    }
    if (((port_get(data, ((6 + (y * w)) + x)) != 0) || (port_get(data, ((6 + (gy * w)) + gx)) != 0))) {
        return [0];
    }
    nx = port_abs_num((gx - x));
    ny = port_abs_num((gy - y));
    sx = -(1);
    sy = -(1);
    if ((gx > x)) {
        sx = 1;
    }
    if ((gy > y)) {
        sy = 1;
    }
    ix = 0;
    iy = 0;
    while (((ix < nx) || (iy < ny))) {
        decision = (((1 + (2 * ix)) * ny) - ((1 + (2 * iy)) * nx));
        if ((decision == 0)) {
            if (((port_get(data, (((6 + (y * w)) + x) + sx)) != 0) || (port_get(data, ((6 + ((y + sy) * w)) + x)) != 0))) {
                return [0];
            }
            x += sx;
            y += sy;
            ix += 1;
            iy += 1;
        } else {
            if ((decision < 0)) {
                x += sx;
                ix += 1;
            } else {
                y += sy;
                iy += 1;
            }
        }
        if ((port_get(data, ((6 + (y * w)) + x)) != 0)) {
            return [0];
        }
    }
    return [1];
}
